                res.framing = d.framing;
                res.dataQuality = ds.dataQuality;
                res.serviceQuality = ds.serviceQuality;
                res.valueAdd = ds.valueAdd;
                res.adoption = ds.adoption;
                res.churn = ds.churn;
                res.roi = ds.roi;
                res.paybackMonths = ds.paybackMonths;
                res.breakevenAdoption = ds.breakevenAdoption;
                res.capRemaining = ds.capRemaining;
