        getHint(state, results) {
            if (!results) return null;
            var t = window.mySimulation.t.bind(window.mySimulation);
            var ds = state.domainState;
            var period = results.period;

            if (period === 1) {
                var density = results.affordanceDensity || 0;
                if (ds.activatedSignals.indexOf('device') !== -1 || ds.activatedSignals.indexOf('geo') !== -1) {
                    return t('hint_volume_trap');
                }
                if (density < 1.5) return t('hint_low_density');
                return t('hint_good_signals');
            }
            if (period === 2) {
                if (results.signalFit < 0.5) return t('hint_starved_bet');
                if (results.bet === 'b2b') return t('hint_b2b_churn');
                return t('hint_good_bet');
            }
            if (period === 3) {
                if (ds.gtm < 1.0) return t('hint_starved_launch');
                if (ds.dataEng > 3.5) return t('hint_over_engineered');
                if (ds.adoption < ds.targetAdoption - 5) return t('hint_target_gap');
                return t('hint_balanced');
            }
            // period 4
            if (results.framing === 'features') return t('hint_feature_list');
            if (ds.churn > CHURN_TARGET) return t('hint_churn_unbent');
            return t('hint_thesis_proven');
        }

