        _computeScore(ds) {
            var churn = ds.churn;
            var valueAdd = ds.valueAdd;
            var adoption = ds.adoption;
            var roi = ds.roi || 0;
            var payback = ds.paybackMonths;
            var capLeft = ds.capRemaining;
            var score = 0;
            if (churn <= CHURN_TARGET - 0.4) score += 28;
            else if (churn <= CHURN_TARGET) score += 22;
            else if (churn <= CHURN_TARGET + 0.4) score += 12;
            else score += 4;
            if (valueAdd >= 70) score += 22;
            else if (valueAdd >= 55) score += 17;
            else if (valueAdd >= 40) score += 10;
            else score += 4;
            if (adoption >= 22) score += 20;
            else if (adoption >= 15) score += 15;
            else if (adoption >= 9) score += 8;
            else score += 3;
            if (roi >= 60 && payback !== null && payback <= 12) score += 20;
            else if (roi >= 30) score += 14;
            else if (roi >= 0) score += 8;
            else score += 2;
            if (capLeft >= -0.001 && capLeft <= 0.6) score += 10;
            else if (capLeft > 0.6) score += 5;
            else score += 0;
            return score;
        }

        _grade(s) {
            if (s >= 82) return 'A';
            if (s >= 66) return 'B';
            if (s >= 50) return 'C';
            return 'D';
        }

        _t() {
            return (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? window.mySimulation.t.bind(window.mySimulation)
                : function (k) { return k; };
        }

        formatCompletionMessage(summary) {
            var t = this._t();
            summary = summary || {};
            var score = (typeof summary.score === 'number') ? summary.score
                      : (typeof summary.overallScore === 'number') ? summary.overallScore : 0;
            var verdict = summary.performance || '';
            var insights = summary.insights || [];
            var items = insights.map(function (s) { return '<li>' + s + '</li>'; }).join('');
            return ''
                + '<div class="sigserv-completion">'
                +   '<div class="sigserv-completion-heading">' + t('comp_heading') + '</div>'
                +   '<div class="sigserv-completion-verdict">' + verdict + '</div>'
                +   '<div class="sigserv-completion-score"><span>' + t('comp_score_label') + '</span>'
                +     '<strong>' + score + '/100</strong></div>'
                +   '<div class="sigserv-completion-insights-heading">' + t('comp_insights_heading') + '</div>'
                +   '<ul class="sigserv-completion-insights">' + items + '</ul>'
                + '</div>';
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var t = window.mySimulation.t.bind(window.mySimulation);
            var last = history[history.length - 1].results || {};
            var ds = window.mySimulation.state.domainState;

            var churn = ds.churn;
            var valueAdd = ds.valueAdd;
            var adoption = ds.adoption;
            var roi = ds.roi || 0;
            var payback = ds.paybackMonths;
            var capLeft = ds.capRemaining;
            var arrested = round1(CHURN_START - churn);

            var score = this._computeScore(ds);

            var performance = t('rank_dead');
            if (score >= 82) performance = t('rank_proven');
            else if (score >= 66) performance = t('rank_strong');
            else if (score >= 50) performance = t('rank_partial');

            var insights = [];
            if (ds.activatedSignals.indexOf('device') !== -1 || ds.activatedSignals.indexOf('geo') !== -1) insights.push(t('ins_volume'));
            if (ds.signalFit < 0.6) insights.push(t('ins_starved'));
            if (ds.gtm < 1.0) insights.push(t('ins_launch'));
            if (last.framing === 'features') insights.push(t('ins_features'));
            if (ds.chosenBet === 'b2b') insights.push(t('ins_b2b'));
            if (payback !== null && payback > 18) insights.push(t('ins_clock'));
            if (churn <= CHURN_TARGET && roi >= 30) insights.push(t('ins_proven'));
            if (insights.length === 0) insights.push(t('ins_default'));

            return {
                finalChurn: churn,
                churnArrested: arrested,
                valueAdd: Math.round(valueAdd),
                adoption: adoption,
                roi: roi,
                paybackMonths: payback === null ? '—' : payback,
                capRemaining: capLeft,
                score: score,
                performance: performance,
                insights: insights
            };
        }

